// Additional UI flows, backed only by the prototype's in-memory state.
const WISH_KINDS=['feed','clean','play','touch','work'];
function wishDefinition(kind=S.wishKind||'feed'){
 const names={feed:[T('想吃点好吃的','A little something tasty'),'food',36],clean:[T('想洗得香香的','A little wash would be lovely'),'bath',36],play:[T('想和你玩一会儿','A little playtime together'),'game',36],touch:[T('想要一个摸摸头','A gentle head pat'),'heart',32],work:[T('一起攒点零花钱','Earn a little pocket money'),'briefcase',48],sleep:[T('想好好睡一觉','A little rest'),'moon',0]};
 const [title,icon,reward]=names[kind]||names.feed;return {title,icon,reward,kind};
}
function recordWish(kind){if(kind===(S.wishKind||'feed'))S.wish=1;if(kind===(S.returnKind||'touch'))S.returnDone=true;}
function runWishAction(kind){if(kind==='feed'){UI.mode='bag';UI.category='food';openModal('storage');}else if(kind==='touch')dispatch('touch');else if(kind==='work')openModal('work');else dispatch('care',kind);}
function ticketLedger(){return S.dailyTickets??=( {processed:[],granted:[]} );}
function resolveTicket(source,chance){const ledger=ticketLedger();if(ledger.processed.includes(source))return '';ledger.processed.push(source);const roll=(S.day*37+({daily_wish:64,daily_encounter:70,partner_schedule:0})[source])%100;if(ledger.granted.length>=3||roll>=chance)return '';ledger.granted.push(source);S.tickets++;return T(' 额外获得扭蛋券 ×1。',' One bonus gacha ticket!');}
function neighborRole(){const index=ROLES.indexOf(S.role);return ROLES[(index+1)%ROLES.length];}
function neighborTodo(){const role=neighborRole();return homeTodo('gift',T(roleName(role)+' 来做客了',roleName(role)+' is visiting'),T('带来小花束，来收下这份心意','A little bouquet is waiting for you'),'neighbor-visit');}
function ticketSourcesCard(){const ledger=ticketLedger();return '<section class="card" style="margin-top:20px"><div class="card-head"><div><h2>'+T('今天的扭蛋券','Today’s gacha tickets')+'</h2><p class="hint">'+T('每天最多 3 次来源奖励；完成后自动入账。','Up to three source rewards daily, added automatically.')+'</p></div>'+pill(ledger.granted.length+' / 3','ticket')+'</div><div class="gap">'+[
 ['daily_wish',T('完成每日心愿','Daily wish'),T('领奖时有 20% 概率获得','20% chance when claiming'),'home'],
 ['partner_schedule',T('完成三次伙伴日程','Three activities'),T('今日 '+S.scheduleToday+' / 3，完成后必得','Today '+S.scheduleToday+' / 3; guaranteed on completion'),'schedule'],
 ['daily_encounter',T('邻居与日常邂逅','An everyday encounter'),T('每日首次邂逅有 20% 概率获得','20% chance on the first daily encounter'),'home']
 ].map(([id,label,hint,route])=>homeTodo(ledger.granted.includes(id)?'check':'ticket',label,ledger.granted.includes(id)?T('已获得 1 张券','One ticket received'):ledger.processed.includes(id)?T('今日已结算，这次没有抽中','Resolved today; no ticket this time'):hint,'route:'+route)).join('')+'</div></section>';}
function dailyWishRow(){const w=wishDefinition();return homeTodo(w.icon,S.wish?T('小心愿达成，领取奖励','A wish fulfilled, claim your reward'):w.title,T('完成一次 · 奖励 '+w.reward+' 金币','Complete once · '+w.reward+' coins'),'wish');}
function investmentChoices(kind,cost,invested,enabled=true){return '<div class="investment-row">'+[['ten',.1],['quarter',.25],['rest',1]].map(([id,factor])=>{const amount=Math.min(S.coins,Math.max(0,cost-invested),id==='rest'?cost:Math.max(1,Math.floor(cost*factor)));return b(({ten:T('投一成','10%'),quarter:T('投四分之一','25%'),rest:T('投满','Fill')})[id]+' · '+money(amount),'invest-request',kind+':'+amount,'small','',!enabled||!amount);}).join('')+'</div>';}
function requestInvestment(arg){const [kind,raw]=arg.split(':'),amount=Number(raw);if(!Number.isInteger(amount)||amount<=0)return fail('没有可投入的金币。','No coins available to contribute.');const action=kind==='legacy'?'legacy-invest':'invest';if(amount>=10000)return confirmDialog(T('确认这笔投入','Confirm contribution'),T('投入 '+F(amount)+' 金币，进度会保留。','Contribute '+F(amount)+' coins. Progress is retained.'),action,kind==='legacy'?String(amount):arg);return dispatch(action,kind==='legacy'?String(amount):arg);}
function legacySection(){const unlocked=allDreamsDone(),cost=legacyCost(),apples=Math.ceil((S.legacy.level+1)/2);return '<section class="card" style="margin-top:20px"><div class="card-head"><div><p class="eyebrow">PASS IT ON</p><h2>'+T('梦想之后，是传承','Beyond a dream, a legacy')+'</h2><p class="hint">'+T('完成四个梦想后开启，可以分多次投入，已完成的奖杯会保留。','Unlock after all four dreams. Contribute over time and keep your trophies.')+'</p></div>'+pill('Lv.'+S.legacy.level,'award')+'</div>'+(!unlocked?'<p class="notice-box">'+I('lock')+' '+T('先一起完成四类梦想。','Complete all four dreams first.')+'</p>':'')+'<div class="row between wrap" style="margin-top:18px"><span>'+T('已投入','Contributed')+'</span><strong>'+money(S.legacy.invested)+' / '+F(cost)+'</strong></div>'+bar(S.legacy.invested,cost)+investmentChoices('legacy',cost,S.legacy.invested,unlocked)+'<p class="hint">'+T('完成本级还需要 '+apples+' 个金苹果。','Complete this level with '+apples+' golden apples.')+'</p>'+b(T('完成传承 Lv.'+(S.legacy.level+1),'Complete legacy Lv.'+(S.legacy.level+1)),'legacy-confirm','','primary block','award',!unlocked||S.legacy.invested<cost||S.inventory.golden_apple<apples)+'<div class="divider"></div><div class="row between wrap"><h3>'+T('金苹果兑换','Golden apple exchange')+'</h3>'+pill('1 → 100','heart')+'</div><p class="hint" style="margin:12px 0">'+T('持有 '+F(S.inventory.golden_apple)+' 个，可兑换 '+F(S.inventory.golden_apple*100)+' 小心心。','You have '+F(S.inventory.golden_apple)+' apples, worth '+F(S.inventory.golden_apple*100)+' hearts.')+'</p><div class="row wrap">'+[1,10,'all'].map(n=>b(n==='all'?T('全部兑换','Exchange all'):T('兑换 '+n+' 个','Exchange '+n),'gold-exchange-request',n,'','exchange',!unlocked||S.inventory.golden_apple<(n==='all'?1:n))).join('')+'</div></section>';}
function scheduleOffers(){const count=S.scheduleBoardCount||3,base=[['study',0],['cooking',1],['garden',2],['exercise',0],['cooking',2]];return base.slice(0,count).map(([category,size],index)=>{const k=SKILLS[(SKILLS.indexOf(category)+S.day-1)%4];return {...scheduleOffer(size),category:k,size,index,id:S.day+':'+index,hunger:[4,10,18][size],mood:[2,5,8][size],neighbor:index===1?neighborRole():null};});}
function schedulePageFull(){const offers=scheduleOffers(),filtered=UI.scheduleCategory==='all'?offers:offers.filter(o=>o.category===UI.scheduleCategory);return pageTitle(T('给伙伴一点自己的时间','A little time of their own'),'LITTLE DAILY ACTIVITIES',b(T('技能与加成','Skills & bonuses'),'skills','','','award'))+'<div class="skill-grid">'+SKILLS.map(k=>'<button data-tone="'+SKILL_TONES[k]+'" class="skill-card '+(UI.scheduleCategory===k?'active':'')+'" data-act="schedule-category" data-arg="'+k+'"><span class="tile-icon">'+I(SKILL_ICONS[k])+'</span><div class="grow"><h3>'+skillName(k)+'</h3><small class="muted">Lv.'+S.skills[k].level+' · '+skillEffect(k)+'</small>'+bar(S.skills[k].level,10)+'</div></button>').join('')+'</div>'+(S.schedule?scheduleRunning():S.schedulePending?scheduleSettlement():'')+'<section class="card" style="margin-top:20px"><div class="card-head"><div><h2>'+T('今天的小日程','Today’s activity board')+'</h2><p class="hint">'+T('今日完成 '+S.scheduleToday+' / 3 · 每项日程每天可完成一次','Completed '+S.scheduleToday+' / 3 · Each offer can be completed once a day')+'</p></div>'+b(T('查看全部','Show all')+' · '+offers.length,'schedule-category','all','small','calendar')+'</div><div class="offer-grid">'+(filtered.length?filtered.map(o=>{const done=S.completedOffers.includes(o.id),busy=!!S.schedule||!!S.schedulePending;return '<article class="offer-card" data-tone="'+SKILL_TONES[o.category]+'"><div class="offer-art">'+I(SKILL_ICONS[o.category])+'</div><div class="offer-copy"><p class="eyebrow">'+[T('轻轻开始','A gentle start'),T('认真一点','A little more time'),T('沉浸其中','Settle into it')][o.size]+'</p><h3>'+skillName(o.category)+' · '+o.minutes+' '+T('分钟','min')+'</h3><p class="hint">'+T('体力 −'+o.energy+' · 饱腹 −'+o.hunger+' · 心情 −'+o.mood,'Energy −'+o.energy+' · Hunger −'+o.hunger+' · Mood −'+o.mood)+'</p>'+(o.neighbor?pill(T('和 '+roleName(o.neighbor)+' 同行','With '+roleName(o.neighbor)),'heart'):'')+'<div class="row between wrap" style="margin:14px 0">'+money(o.coins)+pill(S.skills[o.category].level===10?T('大师次数 +1','Mastery +1'):T('经验 +'+o.xp,'XP +'+o.xp),'award')+'</div>'+b(done?T('今日已完成','Done today'):busy?T('先完成当前日程','Finish the current activity'):T('开始日程','Start activity'),'start-schedule',o.index,'primary block','play',done||busy||S.sleeping||S.stats.energy<o.energy||S.scheduleToday>=3)+'</div></article>';}).join(''):'<div class="empty">'+T('今天暂时没有这一类日程，看看其他安排吧。','No offers in this category today. Explore the other activities.')+b(T('查看全部日程','View all activities'),'schedule-category','all')+'</div>')+'</div></section>'+scheduleMilestones()+ticketSourcesCard();}
function scheduleMilestones(){return '<section class="card soft" style="margin-top:20px"><h3>'+T('全技能成长里程碑','Growing every skill')+'</h3><div class="metric-grid" style="margin-top:16px">'+[3,6].map(level=>{const count=SKILLS.filter(k=>S.skills[k].level>=level).length;return '<div class="metric"><small>'+T('全技能 Lv.'+level,'Every skill Lv.'+level)+'</small><strong>'+count+' / 4</strong><p class="hint">'+T('达成后金币 '+(level===3?'+5%':'+15%')+'，次日 '+(level===3?4:5)+' 项日程可选。','Complete for '+(level===3?5:15)+'% coins and '+(level===3?4:5)+' offers from the next day.')+'</p></div>';}).join('')+'</div></section>';}
function skillDetails(){return SKILLS.map(k=>{const skill=S.skills[k],copy=DATA.copy[UI.lang].schedule;return '<section class="card soft" data-tone="'+SKILL_TONES[k]+'" style="margin-bottom:14px"><div class="row between"><h3>'+skillName(k)+'</h3>'+pill('Lv.'+skill.level)+'</div><p class="hint" style="margin:10px 0">'+(skill.level<10?T('经验 '+skill.xp+' / 50','XP '+skill.xp+' / 50'):T('大师完成次数 '+skill.master+' / 60','Master completions '+skill.master+' / 60'))+'</p>'+bar(skill.level<10?skill.xp:skill.master,skill.level<10?50:60)+'<div class="requirements" style="margin-top:14px">'+[2,4,5,7,8,9,10].map(level=>'<span class="'+(skill.level>=level?'met':'unmet')+'">'+I(skill.level>=level?'check':'lock')+E(copy.passives['level'+level])+'</span>').join('')+'</div><p class="notice-box">'+E(copy.masterPassives[k][skill.master>=60?'advanced':'base'])+'</p><p class="hint" style="margin-top:10px">'+T('大师 10 次：体力减免 15%；30 次：分类金币 +10%；60 次：强化长期被动。','10 mastery: 15% energy saving; 30: +10% category coins; 60: stronger long-term passive.')+'</p></section>';}).join('');}
function energyInterval(){return S.sleeping?(UI.season==='winter'?162:180):UI.weather==='breezy'?240:300;}
function energyHint(){return S.schedule?T('日程中暂停恢复','Recovery paused during activity'):S.stats.energy>=cap()?T('体力已充足','Energy is full'):T('下次恢复 '+timeText(energyInterval()-(S.simulatedSeconds||0)%energyInterval()),'Next recovery '+timeText(energyInterval()-(S.simulatedSeconds||0)%energyInterval()));}
function statusDetails(){return '<div class="gap">'+STAT_DEFS.map(([key,zh,en,icon,color])=>'<div class="row between"><span>'+I(icon)+' '+T(zh,en)+'</span><strong>'+F(S.stats[key])+' / '+cap()+'</strong></div>').join('')+'</div><div class="divider"></div><p class="hint">'+energyHint()+'</p><p class="hint" style="margin-top:10px">'+environmentExplanation()+'</p><div class="row wrap" style="margin-top:20px">'+b(T('去背包补充','Open supplies'),'storage','bag','','bag')+b(S.sleeping?T('叫醒','Wake up'):T('休息一下','Get some rest'),'care','sleep','','moon',!!S.schedule)+'</div>';}
function saveSettingsFull(){const rollback=!!S.importRollback;return '<section class="card"><div class="card-head"><div><h2>'+T('好好保存，每一天','Keep every day safe')+'</h2><p class="hint">'+T('备份与文件仅用于这份界面原型。','Backups and files belong to this UI prototype.')+'</p></div>'+b(T('手动备份','Back up now'),'backup','','primary','save')+'</div>'+settingToggle(T('自动备份','Automatic backups'),T('推进演示天数时生成备份','Create backups as demo days advance'),S.autoBackup,'toggle-backup')+'<div class="form-grid" style="margin-top:18px">'+numberField('backup-days',T('备份间隔（天）','Backup interval (days)'),S.backupDays,'backup-days',1,30)+'<label class="field"><span>'+T('备份文件名','Backup filename')+'</span><input class="text-field" data-change="backup-target" value="'+E(S.backupTarget)+'"></label></div><div class="row wrap" style="margin-top:16px">'+b(T('选择备份文件','Choose backup file'),'choose-backup','','','save')+(S.backupFileStatus==='permission'?b(T('重新授权','Reauthorize'),'authorize-backup','','primary','refresh'):'')+'</div><p class="hint" style="margin-top:10px">'+({memory:T('当前保存在原型内存','Currently kept in prototype memory'),ready:T('演示备份文件已就绪','Demo backup file ready'),permission:T('演示文件授权已过期，点击重新授权','Demo permission expired. Reauthorize to continue.')})[S.backupFileStatus]+'</p><div class="divider"></div><h3>'+T('备份列表','Backup history')+'</h3>'+S.backups.map((x,i)=>'<div class="backup-row"><span class="tile-icon">'+I('save')+'</span><div class="grow"><h3>'+E(x.label)+'</h3><p class="hint">'+E(x.role)+' · Lv.'+x.level+' · '+F(x.coins)+' '+T('金币','coins')+'</p></div><div class="row wrap">'+b(T('恢复','Restore'),'restore-confirm',i,'small','refresh')+iconButton(T('导出这份备份','Export this backup'),'export-backup',i,'download')+'</div></div>').join('')+'</section><section class="card" style="margin-top:20px"><h2>'+T('导出与分享存档','Export and share a save')+'</h2><div class="row wrap" style="margin-top:18px">'+b(T('查看 / 复制文本','View / copy text'),'save-export','','','copy')+b(T('下载演示文件','Download demo file'),'download-demo','','primary','download')+b(T('分享存档文件','Share save file'),'share-save','','','image')+'</div></section><section class="card" style="margin-top:20px"><h2>'+T('导入与恢复','Import and restore')+'</h2><p class="hint" style="margin:12px 0">'+T('导入前会显示摘要，并自动保留当前进度的备份。仅接受本原型导出的 JSON。','Review the summary before import. Current progress is backed up automatically. Accepts only JSON exported by this prototype.')+'</p><div class="row wrap">'+b(T('选择演示文件','Choose demo file'),'pick-demo-file','','','upload')+b(T('使用内置示例','Use built-in sample'),'import-preview','','','gift')+(rollback?b(T('恢复导入前进度','Undo last import'),'rollback-import','','','refresh'):'')+'</div><input id="demo-import-file" type="file" accept=".json,application/json" data-file="demo-save" hidden><label class="field" style="margin-top:18px"><span>'+T('或粘贴演示存档文本','Or paste demo save text')+'</span><textarea class="mono" id="import-demo-text" data-input="import-demo-text" placeholder="'+T('粘贴从此原型导出的 JSON','Paste JSON exported from this prototype')+'">'+E(UI.importText||'')+'</textarea></label>'+b(T('检查文本并导入','Review pasted save'),'import-pasted','','primary block','upload')+'</section>'+cloudSettings();}
function cloudSettings(){return '<section class="card" style="margin-top:20px"><div class="card-head"><div><h2>'+T('云端同步','Cloud sync')+'</h2><p class="hint">'+T('B 站账号 · 本地模拟服务','Bilibili account · Local simulation')+'</p></div>'+pill(UI.edition==='bilibili'?T('演示已登录','Demo signed in'):T('普通版','Standard'),'cloud')+'</div><p class="notice-box">'+(S.cloud?E(S.cloud.label):T('暂时没有云端演示记录。','No cloud demo snapshot yet.'))+'</p><div class="row wrap" style="margin:18px 0">'+b(T('上传到云端','Upload to cloud'),'cloud-upload-request','','primary','upload',UI.edition!=='bilibili')+b(T('恢复云端进度','Restore cloud'),'cloud-restore','','','download',UI.edition!=='bilibili'||!S.cloud)+(UI.edition!=='bilibili'?b(T('切换 B 站版预览','Preview Bilibili edition'),'route','preview','','sliders'):'')+'</div>'+settingToggle(T('云同步提醒','Cloud sync reminders'),T('有未同步进度时提醒保存','Remind when progress needs syncing'),S.cloudReminder,'toggle-cloud-reminder')+'</section>';}
function demoImportPreview(data){const demo=data.demo||{format:'pocket-ui-prototype-v2',version:1,state:{...seedState('daily'),role:'doro'}},s=demo.state;return {title:T('导入前确认','Review import'),cls:'medium',body:'<p class="notice-box">'+T('确认后替换这份原型进度，当前内容会先备份。外观与环境保持。','Replaces prototype progress after backing it up. Appearance and environment are kept.')+'</p><div class="metric-grid" style="margin-top:20px"><div class="metric"><small>'+T('伙伴','Companion')+'</small><strong>'+E(s.names[s.role]||roleName(s.role))+'</strong></div><div class="metric"><small>'+T('等级','Level')+'</small><strong>'+s.level+'</strong></div><div class="metric"><small>'+T('金币','Coins')+'</small><strong>'+F(s.coins)+'</strong></div></div><p class="hint" style="margin-top:15px">'+E(data.filename||'Pocket-demo.json')+'</p>',footer:b(T('取消','Cancel'),'close')+b(T('确认导入','Import save'),'apply-import','','primary','upload')};}
function parseDemoText(text){
 if(text.length>2000000)throw new Error(T('演示文件过大。','The demo file is too large.'));
 const data=JSON.parse(text),r=data?.state;if(data?.format!=='pocket-ui-prototype-v2'||!r||!['new','daily','end'].includes(r.preset))throw new Error(T('请选择本原型导出的演示存档。','Choose a save exported by this prototype.'));
 const finite=n=>Number.isFinite(n)&&n>=0;const valid=r.names&&typeof r.names==='object'&&typeof r.role==='string'&&[r.coins,r.hearts,r.tickets,r.level,r.ageDays,r.day].every(finite)&&r.level>=1&&r.level<=99&&STAT_DEFS.every(([k])=>finite(r.stats?.[k]))&&DATA.items.every(i=>finite(r.inventory?.[i.id]??0))&&Array.isArray(r.garden)&&r.garden.length===5&&r.garden.every(g=>g&&['empty','growing','ready','withered','locked'].includes(g.state)&&(!g.tree||TREE_IDS.includes(g.tree))&&finite(g.seconds)&&finite(g.harvests))&&SKILLS.every(k=>finite(r.skills?.[k]?.level)&&finite(r.skills?.[k]?.xp)&&finite(r.skills?.[k]?.count)&&finite(r.skills?.[k]?.master)&&finite(r.dreams?.[k]?.stage)&&r.dreams[k].stage<=5&&finite(r.dreams[k].invested))&&Array.isArray(r.claimed)&&r.claimed.every(x=>typeof x==='string')&&Array.isArray(r.achievementClaimed)&&r.achievementProgress&&r.focus&&['focus','rest'].includes(r.focus.phase)&&[r.focus.focus,r.focus.rest,r.focus.remaining,r.focus.round,r.focus.rounds,r.focus.today].every(finite)&&r.gacha&&Array.isArray(r.gacha.results)&&Array.isArray(r.gacha.history)&&r.cards&&r.legacy&&finite(r.legacy.level)&&finite(r.legacy.invested);
 if(!valid)throw new Error(T('演示存档的字段不完整或数值无效，当前进度未改动。','The demo save has missing or invalid fields. Current progress is unchanged.'));
 const rewardValid=x=>x&&finite(x.amount)&&['coins','hearts','item'].includes(x.kind)&&typeof x.rarity==='string'&&(x.kind!=='item'||!!itemById(x.item));
 const detailValid=Number.isInteger(r.day)&&Number.isInteger(r.level)&&Object.values(r.names).every(x=>typeof x==='string')&&Object.values(r.achievementProgress).every(finite)&&[r.gacha.total,r.gacha.pity].every(finite)&&r.gacha.results.every(rewardValid)&&r.gacha.history.every(h=>h&&typeof h.time==='string'&&['apple','heart'].includes(h.machine)&&Array.isArray(h.results)&&h.results.every(rewardValid))&&(!r.review||[r.review.activeDays,r.review.itemsUsed,r.review.focusCount,r.review.focusMinutes,...Object.values(r.review.careActions||{})].every(finite));
 if(!detailValid)throw new Error(T('演示存档的记录内容无效，尚未替换当前进度。','The demo contains invalid records. Current progress has not been replaced.'));
 if(r.schedule&&!['category','minutes','energy','coins','xp','remaining','total'].every(k=>k==='category'?SKILLS.includes(r.schedule[k]):finite(r.schedule[k])))throw new Error(T('日程数据无效。','Invalid activity data.'));
 if(r.schedulePending&&!SKILLS.includes(r.schedulePending.category))throw new Error(T('结算数据无效。','Invalid activity result.'));
 return {...data,state:{...seedState(r.preset),...r,backups:[],cloud:null,importRollback:null,mods:[{id:'cloud_mod',name:'云朵旅人',nameEn:'Cloud traveler',enabled:r.role==='cloud_mod'}]}};
}
function stageDemoImport(text,filename){try{const demo=parseDemoText(text);openModal('import-preview',{demo,filename});return true;}catch(error){return fail(T('导入失败：','Import failed: ')+error.message);}}
function importDemo(){const modal=UI.stack.at(-1),demo=modal?.data?.demo||{format:'pocket-ui-prototype-v2',state:{...seedState('daily'),role:'doro'}},before=exportDemo();createBackup(T('导入前备份','Before import'));if(!restoreData(demo))return false;S.importRollback=before;UI.importText='';render();notify(T('演示存档已导入，可在存档页恢复导入前进度。','Demo imported. Undo the import from Saves.'),'success');return true;}
function recoveryPageFull(){return pageTitle(T('别担心，小日子还在','Your little days are still here'),'LET’S GET YOU HOME')+'<section class="card" style="max-width:800px;margin:auto"><div class="reward-banner">'+petImage('idle')+'<div><h2>'+T('发现一份异常演示进度','An issue with the demo progress')+'</h2><p class="hint">'+T('内容未通过校验，先选择一种恢复方式。','The data did not pass validation. Choose a recovery option.')+'</p></div></div><label class="field" style="margin-top:20px"><span>'+T('可恢复的备份','Available backups')+'</span><select class="text-field" data-change="recovery-index">'+S.backups.map((x,i)=>'<option value="'+i+'"'+(Number(UI.recoveryIndex||0)===i?' selected':'')+'>'+E(x.label)+' · '+E(x.role)+'</option>').join('')+'</select></label><div class="row wrap" style="margin-top:18px">'+b(T('恢复所选备份','Restore selected'),'recovery-restore','','primary','refresh',!S.backups.length)+b(T('重新尝试读取','Retry reading'),'recovery-retry','','','refresh')+b(T('导出异常原文','Export damaged text'),'export-damaged','','','download')+'</div><details style="margin-top:20px"><summary>'+T('查看异常原文','View damaged text')+'</summary><textarea class="mono" readonly>'+E(damagedDemoText())+'</textarea></details><div class="divider"></div><div class="gap">'+b(T('选择文件 / 粘贴文本导入','Import a file / pasted text'),'menu-route','save','block','upload')+b(T('新建进度','Start fresh'),'new-confirm','','danger block','plus')+b(T('继续当前演示','Continue current demo'),'route','home','block','back')+'</div></section>';}
function damagedDemoText(){return '{"format":"pocket-ui-prototype-v2","version":1,"state":{"name":"Furo","coins":';}
function checkCloudReminder(){if(UI.page==='settings'&&UI.settings==='save'&&S.cloudSnoozed&&S.cloudReminder){S.cloudSnoozed=false;notify(T('上次暂缓了云同步，记得保存这段新进度。','Your cloud sync reminder is back. Save the latest little moments.'));}}
function previewAdditions(){return '<section class="card" style="margin-top:20px"><h2>'+T('原有功能与边界状态','Original features and edge cases')+'</h2><div class="form-grid" style="margin-top:18px"><label class="field"><span>'+T('每日心愿类型','Daily wish type')+'</span><select class="text-field" data-change="wish-kind">'+WISH_KINDS.map(k=>'<option value="'+k+'"'+((S.wishKind||'feed')===k?' selected':'')+'>'+wishDefinition(k).title+'</option>').join('')+'</select></label><label class="field"><span>'+T('回归小目标','Return goal')+'</span><select class="text-field" data-change="return-kind">'+['touch','feed','clean','sleep'].map(k=>'<option value="'+k+'"'+((S.returnKind||'touch')===k?' selected':'')+'>'+wishDefinition(k).title+'</option>').join('')+'</select></label></div><div class="row wrap" style="margin-top:18px">'+b(T('邻居来访','Neighbor visit'),'preview-neighbor','','','gift')+b(T('模拟备份授权过期','Expire demo file permission'),'expire-backup','','','save')+b(T('低清洁睡觉提醒','Low cleanliness sleep prompt'),'preview-low-clean','','','bath')+b(T('版本功能说明','Edition notice'),'edition-notice','','','info')+b(T('模拟云同步提醒','Cloud sync reminder'),'cloud-reminder','','','cloud')+'</div></section>';}
function fullTrophyCabinet(){const copy=DATA.copy[UI.lang].trophies,stages=[1,3,5],tiers=['bronze','silver','gold'];let count=0;const cards=SKILLS.flatMap(k=>tiers.map((tier,index)=>{const unlocked=S.dreams[k].stage>=stages[index];if(unlocked)count++;const effectKey={study:'schedule',cooking:'food',garden:'garden',exercise:'energy'}[k],effectValue=['study','cooking'].includes(k)?[1.25,1.5,2][index]:[25,50,100][index];return '<article class="trophy '+(unlocked?'':'locked')+'" data-tone="'+SKILL_TONES[k]+'">'+I(unlocked?'award':'lock')+'<h3>'+E(copy.names[k][tier])+'</h3><p class="hint">'+E(copy.effects[effectKey].replace('{value}',effectValue))+'</p><small>'+T(unlocked?'已解锁':'完成第 '+stages[index]+' 阶段解锁',unlocked?'Unlocked':'Unlock at stage '+stages[index])+'</small></article>';})).join('');return '<div class="row between"><p class="hint">'+E(copy.summary)+'</p>'+pill(count+' / 12','award')+'</div><div class="trophy-grid">'+cards+'</div><section class="card soft" data-tone="lilac"><div class="row between"><h3>'+I(count===12?'sparkles':'lock')+' '+E(copy.names.diamond)+'</h3>'+pill(count===12?T('已解锁','Unlocked'):T('收集 12 座奖杯','Collect all 12'))+'</div><p class="hint" style="margin-top:12px">'+E(copy.effects.diamond)+'</p></section><p class="hint" style="margin-top:14px">'+T('传承纪念 Lv.'+S.legacy.level+' · 已收藏奖杯永久保留。','Legacy keepsake Lv.'+S.legacy.level+' · Collected trophies are retained.')+'</p>';}
const EXTRA_MODALS={
 'release-notes':()=>({title:T('版本发布记录','Release history'),cls:'medium',body:'<p class="eyebrow">POCKET · 1.7.1</p><h3>'+T('小窝的新变化','A little better at home')+'</h3><ul><li>'+T('优化小窝布局、格子物品操作和通知。','Improved home layout, item grids and notifications.')+'</li><li>'+T('恢复完整的存档、日程和梦想操作。','Restored save, activity and dream controls.')+'</li></ul><p class="hint">'+T('这里展示本地版本页，下载仍走原型演示流程。','This is a local release page. Downloads use the prototype’s simulated flow.')+'</p>',footer:b(T('更新前备份','Back up first'),'menu-route','save','','save')+b(T('下载更新','Download update'),'download-update','','primary','download')}),
 'app-share':()=>({title:T('分享 Pocket','Share Pocket'),cls:'medium',body:sharePoster()+'<p class="hint" style="margin-top:18px">'+T('示例分享链接：','Demo share link: ')+'https://pocpet.example/demo</p>',footer:b(T('复制示例链接','Copy demo link'),'copy-share-link','','','copy')+b(T('保存伙伴名片','Save companion card'),'download-card','profile','primary','download')}),
 'neighbor-visit':()=>({title:T('邻居来做客','A neighbor’s visit'),cls:'small',body:'<div class="reward-banner">'+petImage('happy',neighborRole())+'<div><h3>'+roleName(neighborRole())+'</h3><p class="hint">'+T('路过花园，看见这束花就想到了你。今天也要开心呀！','I saw these flowers and thought of you. Have a lovely day!')+'</p></div></div><div class="neighbor-present">'+img('small_bouquet')+'<div><strong>'+T('小花束 ×1','Little bouquet ×1')+'</strong><p class="hint">'+T('收下后会放进背包','Added to your bag when claimed')+'</p></div></div>',footer:b(T('收下心意','Accept the gift'),'neighbor-gift','','primary','gift',!!S.neighborGifts)}),
 'status-details':()=>({title:T('伙伴的状态','Companion status'),cls:'small',body:statusDetails()}),
 'import-preview':demoImportPreview,
 'choose-backup':()=>({title:T('选择演示备份文件','Choose a demo backup file'),cls:'small',body:'<label class="field"><span>'+T('文件名','Filename')+'</span><input class="text-field" data-input="backup-candidate" value="'+E(UI.backupCandidate||S.backupTarget)+'"></label><p class="hint" style="margin-top:14px">'+T('这里模拟文件选择和授权流程，点击下载时才生成实际文件。','File selection and permission are simulated. An actual file is generated only when you choose Download.')+'</p>',footer:b(T('使用这个文件','Use this file'),'select-backup','','primary','save')}),
 'share-save':()=>({title:T('分享存档文件','Share a save file'),cls:'small',body:'<div class="reward-banner">'+I('save')+'<div><h3>'+E(S.backupTarget)+'</h3><p class="hint">'+T('已准备好原型演示文件','Prototype save prepared')+'</p></div></div><p class="hint" style="margin-top:18px">'+T('本地演示分享流程，可下载文件或复制内容后自行分享。','Local sharing preview. Download the file or copy its contents to share.')+'</p>',footer:b(T('复制内容','Copy contents'),'copy-demo','','','copy')+b(T('下载文件','Download file'),'download-demo','','primary','download')}),
 'edition-notice':()=>({title:T('当前版本的功能','Features in this edition'),cls:'medium',body:'<table class="prob-table"><thead><tr><th>'+T('功能','Feature')+'</th><th>'+T('普通版','Standard')+'</th><th>'+T('B 站版','Bilibili')+'</th></tr></thead><tbody>'+[[T('养成、花园、日程、梦想','Care, garden, activities, dreams'),true,true],[T('图片保存与分享','Save and share images'),true,true],[T('改名与自定义 Mod','Rename and custom Mods'),true,false],[T('账号云同步','Account cloud sync'),false,true]].map(([label,a,c])=>'<tr><td>'+label+'</td><td>'+T(a?'支持':'不可用',a?'Available':'Unavailable')+'</td><td>'+T(c?'支持':'不可用',c?'Available':'Unavailable')+'</td></tr>').join('')+'</tbody></table>',footer:b(T('存档与备份','Saves & backups'),'menu-route','save','','save')+b(T('切换版本预览','Preview another edition'),'route','preview','primary','sliders')}),
 'cloud-reminder':()=>({title:T('保存这段新进度','Save your latest progress'),cls:'small',body:'<p>'+T('小窝有新的收获，记得同步一份演示进度。','There are new little moments at home. Keep a synced copy of your demo progress.')+'</p>',footer:b(T('稍后提醒','Remind me later'),'snooze-cloud')+b(T('这次先不提醒','Dismiss this time'),'close')+b(T('去同步','Sync now'),'menu-route','save','primary','cloud')}),
};
const EXTRA_ACTIONS={
 'neighbor-visit':()=>openModal('neighbor-visit'),
 'neighbor-gift':()=>{if(S.neighborGifts)return fail('今天已经收到邻居的礼物了。','You already received today’s gift.');const name=roleName(neighborRole());S.neighborGifts=1;addItem('small_bouquet');UI.stack=[];S.lastEvent=T(name+' 送来小花束：今天也要开心呀！',name+' brought a bouquet: have a lovely day!');const extra=resolveTicket('daily_encounter',20);render();notify(S.lastEvent+extra,'success');return true;},
 'preview-neighbor':()=>{S.neighborGifts=0;go('home');},
 wish:()=>{if(S.wishClaimed)return false;if(!S.wish)return runWishAction(S.wishKind||'feed');const reward=wishDefinition().reward;S.wishClaimed=true;S.coins+=reward;const extra=resolveTicket('daily_wish',20);render();notify(T('心愿达成！收下 '+reward+' 金币。','Wish fulfilled! '+reward+' coins received.')+extra,'success');return true;},
 'return-task':()=>S.returnDone?eventGift('return'):runWishAction(S.returnKind||'touch'),
 'status-details':()=>openModal('status-details'),
 'golden-apple-use':()=>{S.suppressAppleConfirm=true;UI.mode='bag';UI.selected='golden_apple';UI.quantity=1;return transaction();},
 'sleep-confirmed':()=>care('sleep',true),
 'preview-low-clean':()=>{S.stats.cleanliness=Math.round(cap()*.15);S.sleeping=false;go('home');},
 'invest-request':requestInvestment,
 'legacy-invest':raw=>{const amount=Number(raw),remaining=legacyCost()-S.legacy.invested;if(!allDreamsDone()||!Number.isInteger(amount)||amount<=0||amount>remaining||amount>S.coins)return fail('传承未开启，或投入数量无效。','Legacy is locked, or this contribution is invalid.');S.coins-=amount;S.legacy.invested+=amount;render();notify(T('传承投入已保留，可以下次继续。','Legacy contribution saved for next time.'),'success');return true;},
 'legacy-confirm':()=>confirmDialog(T('完成这一级传承','Complete this legacy level'),T('已投入的金币将结算，消耗 '+Math.ceil((S.legacy.level+1)/2)+' 个金苹果，保留已有奖杯。','Settle the contributed coins and spend '+Math.ceil((S.legacy.level+1)/2)+' golden apples. Existing trophies are retained.'),'legacy-execute'),
 'legacy-execute':()=>{const apples=Math.ceil((S.legacy.level+1)/2);if(!allDreamsDone()||S.legacy.invested<legacyCost()||S.inventory.golden_apple<apples)return fail('金币投入或金苹果不足。','More contributions or golden apples are needed.');S.inventory.golden_apple-=apples;S.legacy.invested=0;S.legacy.level++;render();notify(T('完成传承 Lv.'+S.legacy.level+'，纪念奖杯已收好。','Legacy Lv.'+S.legacy.level+' complete. Keepsake collected.'),'success');return true;},
 'gold-exchange-request':raw=>{const n=raw==='all'?S.inventory.golden_apple:Number(raw);if(!allDreamsDone()||!Number.isInteger(n)||n<1||n>S.inventory.golden_apple)return fail('尚未解锁兑换，或金苹果不足。','Exchange is locked, or there are not enough apples.');if(n>1)return confirmDialog(T('确认兑换金苹果','Exchange golden apples'),T('消耗 '+F(n)+' 个金苹果，获得 '+F(n*100)+' 小心心。','Spend '+F(n)+' golden apples for '+F(n*100)+' hearts.'),'gold-exchange',n);return dispatch('gold-exchange',n);},
 'gold-exchange':(raw='1')=>{const n=Number(raw||1);if(!allDreamsDone()||!Number.isInteger(n)||n<1||n>S.inventory.golden_apple)return fail('兑换条件或数量不满足。','Exchange requirements or quantity are not met.');S.inventory.golden_apple-=n;S.hearts+=n*100;render();notify(T('兑换完成，小心心 +'+F(n*100)+'。','Exchange complete. '+F(n*100)+' hearts added.'),'success');return true;},
 'choose-backup':()=>{UI.backupCandidate=S.backupTarget;openModal('choose-backup');},'select-backup':()=>{changeSetting('backup-target',UI.backupCandidate||S.backupTarget);S.backupFileStatus='ready';closeModal();notify(T('演示备份文件已选择。','Demo backup file selected.'),'success');},'authorize-backup':()=>{S.backupFileStatus='ready';render();notify(T('模拟授权已恢复。','Simulated permission restored.'),'success');},'expire-backup':()=>{S.backupFileStatus='permission';go('settings','save');},
 'export-backup':raw=>{const backup=S.backups[Number(raw)];if(!backup)return false;downloadText('Pocket-backup-'+(Number(raw)+1)+'.json',JSON.stringify(backup.data,null,2));notify(T('已请求下载这份备份。','Download requested for this backup.'),'success');return true;},
 'pick-demo-file':()=>$('demo-import-file')?.click(),
 'import-pasted':()=>stageDemoImport(UI.importText||'',T('粘贴的演示文本','Pasted demo text')),
 'apply-import':importDemo,
 'rollback-import':()=>{if(!S.importRollback)return fail('没有可恢复的导入前进度。','There is no previous import to undo.');confirmDialog(T('恢复导入前进度','Undo the last import'),T('当前演示进度先备份，再恢复上次导入之前的内容。','Back up the current demo, then restore the progress before the last import.'),'rollback-import-execute');},
 'rollback-import-execute':()=>{if(!S.importRollback)return false;const data=clone(S.importRollback);createBackup(T('撤销导入前备份','Before undoing import'));restoreData(data);S.importRollback=null;return true;},
 'share-save':()=>openModal('share-save'),
 'recovery-restore':()=>dispatch('restore-confirm',String(UI.recoveryIndex||0)),
 'recovery-retry':()=>notify(T('重新读取完成：异常示例仍未通过校验，请选择备份或导入。','Retried: the damaged sample still fails validation. Choose a backup or import.'),'error'),
 'export-damaged':()=>{downloadText('Pocket-damaged-demo.txt',damagedDemoText(),'text/plain');notify(T('已请求保存异常演示原文。','Download requested for the damaged demo text.'));},
 'cloud-upload-request':()=>confirmDialog(T('上传云端演示进度','Upload demo progress'),T('将当前原型进度保存到模拟云端，替换上一份云端快照。','Save this demo to the simulated cloud, replacing its previous snapshot.'),'cloud-upload'),
 'cloud-reminder':()=>openModal('cloud-reminder'),'snooze-cloud':()=>{S.cloudSnoozed=true;closeModal();notify(T('下次进入云同步页时再提醒。','Reminder deferred until your next cloud sync visit.'));},
 'edition-notice':()=>openModal('edition-notice'),
 'release-notes':()=>openModal('release-notes'),
 'share-app':()=>openModal('app-share'),
 'copy-share-link':()=>copyText('https://pocpet.example/demo'),
};
